CREATE TABLE IF NOT EXISTS trip(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,destination VARCHAR(100) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,invite_code VARCHAR(30),owner_id BIGINT REFERENCES `user`(id),budget BIGINT DEFAULT 0 NOT NULL,status VARCHAR(20) DEFAULT 'ACTIVE' NOT NULL,max_members INT DEFAULT 30 NOT NULL,version BIGINT DEFAULT 0 NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS trip_member(id BIGINT AUTO_INCREMENT PRIMARY KEY,trip_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role VARCHAR(20) DEFAULT 'MEMBER',joined_at TIMESTAMP(6) NOT NULL,UNIQUE(trip_id,user_id));
CREATE TABLE IF NOT EXISTS friendship(id BIGINT AUTO_INCREMENT PRIMARY KEY,user1_id BIGINT NOT NULL,user2_id BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,UNIQUE(user1_id,user2_id),CHECK(user1_id<user2_id));
CREATE TABLE IF NOT EXISTS friend_request(id BIGINT AUTO_INCREMENT PRIMARY KEY,requester_id BIGINT NOT NULL,receiver_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,responded_at TIMESTAMP(6),user_low_id BIGINT NOT NULL,user_high_id BIGINT NOT NULL,pending_low BIGINT GENERATED ALWAYS AS (CASE WHEN status='PENDING' THEN user_low_id ELSE NULL END),pending_high BIGINT GENERATED ALWAYS AS (CASE WHEN status='PENDING' THEN user_high_id ELSE NULL END),UNIQUE(pending_low,pending_high),CHECK(requester_id<>receiver_id));
CREATE TABLE IF NOT EXISTS trip_invitation(id BIGINT AUTO_INCREMENT PRIMARY KEY,trip_id BIGINT NOT NULL,inviter_id BIGINT NOT NULL,invitee_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,responded_at TIMESTAMP(6),pending_invitee BIGINT GENERATED ALWAYS AS (CASE WHEN status='PENDING' THEN invitee_id ELSE NULL END),UNIQUE(trip_id,pending_invitee));
CREATE TABLE IF NOT EXISTS trip_invite_code(id BIGINT AUTO_INCREMENT PRIMARY KEY,trip_id BIGINT NOT NULL,digest CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMP(6) NOT NULL,revoked_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS api_idempotency(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,operation VARCHAR(30) NOT NULL,request_key VARCHAR(36) NOT NULL,request_digest CHAR(64) NOT NULL,response_status INT NOT NULL,response_body TEXT NOT NULL,expires_at TIMESTAMP(6) NOT NULL,UNIQUE(user_id,operation,request_key));
CREATE TABLE IF NOT EXISTS api_rate_limit(bucket_key VARCHAR(100) PRIMARY KEY,hits INT NOT NULL,expires_at TIMESTAMP(6) NOT NULL);

